Insert into CEZAR (ID,DT_INS,CHAT_ID,LANG,KEY,METHOD) values (40,to_date('04-FEB-23','DD-MON-RR'),1275894304,'en',null,'encrypt');
Insert into CEZAR (ID,DT_INS,CHAT_ID,LANG,KEY,METHOD) values (41,to_date('04-FEB-23','DD-MON-RR'),1275894304,'en',8,'encrypt');
Insert into CEZAR (ID,DT_INS,CHAT_ID,LANG,KEY,METHOD) values (42,to_date('04-FEB-23','DD-MON-RR'),1275894304,'ru',null,'encrypt');
